-- Fixtures comunes del runner dentro de transacción rcfito_test; sin imágenes reales.
do $$ begin if current_database()<>'rcfito_test' then raise exception 'Pruebas limitadas a rcfito_test'; end if; end $$;
do $$ declare i int; lot uuid; sub uuid; area numeric; begin
  for i in 1..2 loop
    area:=case when i=1 then 12 else 2 end;
    lot:=public.create_project_lot(jsonb_build_object('project_id',current_setting('test.project'),'field_id','30000000-0000-4000-8000-000000000001','code','IMAGE-'||i,'name','Malla imagen ficticia '||i,'area_ha',area,'infrastructure_type_id','60000000-0000-4000-8000-000000000001'));
    select id into sub from public.lot_subdivisions where lot_id=lot;
    perform public.save_sowing_stage(jsonb_build_object('id',format('e1000000-0000-4000-8000-%s',lpad(i::text,12,'0')),'subdivision_id',sub,'crop_id','40000000-0000-4000-8000-000000000001','variety_id','50000000-0000-4000-8000-000000000001','area_ha',area,'planned_sowing_date','2026-01-01'));
    perform public.transition_sowing_stage(format('e1000000-0000-4000-8000-%s',lpad(i::text,12,'0'))::uuid,'planted','2026-01-02');
  end loop;
end $$;
create function pg_temp.image_stages() returns uuid[] language sql as $$select array['e1000000-0000-4000-8000-000000000001','e1000000-0000-4000-8000-000000000002']::uuid[]$$;
create function pg_temp.image_source(p_area numeric default 14) returns jsonb language sql as $$select jsonb_build_object('kind','image_totals','area_ha',p_area,'products',jsonb_build_array(
  jsonb_build_object('product_id','72000000-0000-4000-8000-000000000001','source_name',E'  Alias OCR ficticio  ','presentation','Bolsa de 1 kg','quantity',28,'unit','kg'),
  jsonb_build_object('product_id','72000000-0000-4000-8000-000000000002','source_name','Nombre OCR segundo','presentation','Envase de 20 L','quantity',1,'unit','L'),
  jsonb_build_object('product_id','72000000-0000-4000-8000-000000000003','source_name','','presentation','','quantity',333,'unit','ml')))$$;
create function pg_temp.image_products() returns jsonb language sql as $$select '[{"product_id":"72000000-0000-4000-8000-000000000001","dose":2000},{"product_id":"72000000-0000-4000-8000-000000000002","dose":71.428571},{"product_id":"72000000-0000-4000-8000-000000000003","dose":23.785714}]'::jsonb$$;
create function pg_temp.image_data(p_id text default 'e9000000-0000-4000-8000-000000000001') returns jsonb language sql as $$select pg_temp.order_data(p_id)||jsonb_build_object('source_text',E'  OCR ficticio\nMallas y contexto revisados  ','source_capture',pg_temp.image_source())$$;
select pg_temp.assert_true((select sum(area_ha)=14 from public.sowing_stages where id=any(pg_temp.image_stages())),'imagen usa etapas completas de doce y dos hectáreas');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||'{"source_capture":[]}',pg_temp.image_stages(),pg_temp.image_products())$q$,'metadatos','origen de imagen requiere objeto');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',pg_temp.image_source()||'{"image_url":"https://example.invalid/picture.png"}'),pg_temp.image_stages(),pg_temp.image_products())$q$,'no permitidos','URLs y campos extra no se archivan como imagen');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',pg_temp.image_source()||'{"kind":"image"}'),pg_temp.image_stages(),pg_temp.image_products())$q$,'Tipo de origen','kind incorrecto rechazado');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',pg_temp.image_source()||'{"area_ha":"14"}'),pg_temp.image_stages(),pg_temp.image_products())$q$,'numérica','superficie textual rechazada');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',pg_temp.image_source(14.00001)),pg_temp.image_stages(),pg_temp.image_products())$q$,'cuatro decimales','área excesiva no se redondea');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',pg_temp.image_source(13.9999)),pg_temp.image_stages(),pg_temp.image_products())$q$,'superficie seleccionada cambió','superficie fuente debe coincidir con suma de etapas');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',pg_temp.image_source()||'{"products":[]}'),pg_temp.image_stages(),pg_temp.image_products())$q$,'uno a cuarenta','imagen requiere productos');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',pg_temp.image_source()||jsonb_build_object('products',(select jsonb_agg(pg_temp.image_source()->'products'->0) from generate_series(1,41)))),pg_temp.image_stages(),pg_temp.image_products())$q$,'uno a cuarenta','imagen limita cuarenta productos antes de recorrerlos');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,0}',(pg_temp.image_source()->'products'->0)||'{"bytes":"AAAA"}')),pg_temp.image_stages(),pg_temp.image_products())$q$,'no permitidos','bytes y campos extra de producto rechazados');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,0}',(pg_temp.image_source()->'products'->0)-'presentation')),pg_temp.image_stages(),pg_temp.image_products())$q$,'faltantes','metadatos de cada renglón son explícitos');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,0,source_name}',to_jsonb(repeat('x',201)))),pg_temp.image_stages(),pg_temp.image_products())$q$,'200','nombre OCR acotado');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,0,presentation}','null')),pg_temp.image_stages(),pg_temp.image_products())$q$,'texto','presentación debe ser texto incluso si está vacía');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,0,quantity}','"28"')),pg_temp.image_stages(),pg_temp.image_products())$q$,'numérica','cantidad total no se infiere desde texto');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,0,quantity}','0')),pg_temp.image_stages(),pg_temp.image_products())$q$,'positiva','cantidad cero rechazada');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,0,quantity}','100000000')),pg_temp.image_stages(),pg_temp.image_products())$q$,'menor','cantidad fuera de rango rechazada');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,0,quantity}','28.0000001')),pg_temp.image_stages(),pg_temp.image_products())$q$,'seis decimales','cantidad fuente no se redondea');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,0,unit}','"cc"')),pg_temp.image_stages(),pg_temp.image_products())$q$,'g, kg, ml o L','unidad de metadatos exige valor canónico');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,0,unit}','"L"')),pg_temp.image_stages(),pg_temp.image_products())$q$,'unidad fija','no se convierte masa a volumen');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,1}',pg_temp.image_source()->'products'->0)),pg_temp.image_stages(),pg_temp.image_products())$q$,'repita','IDs duplicados en totales rechazados');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data(),pg_temp.image_stages(),pg_temp.mixture())$q$,'coincidir exactamente','mezcla sin todos los productos fuente rechazada');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data(),pg_temp.image_stages(),jsonb_set(pg_temp.image_products(),'{0,dose}','2000.000001'))$q$,'dosis no coincide','cálculo del cliente se contrasta en servidor');
select pg_temp.assert_true((select count(*)=0 from public.application_orders),'rechazos de imagen no crean órdenes parciales');
select public.create_application_order(pg_temp.image_data(),pg_temp.image_stages(),pg_temp.image_products());
select pg_temp.assert_true((select source_capture=pg_temp.image_source() and source_text=E'  OCR ficticio\nMallas y contexto revisados  ' from public.application_orders),'metadatos, alias y texto OCR se conservan literales');
select pg_temp.assert_true((select array_agg(dose order by product_id)=array[2000,71.428571,23.785714]::numeric[] from public.application_order_products),'totales kg, L y ml generan dosis por catorce hectáreas con seis decimales');
select pg_temp.assert_true((select source_capture->'products'->1->>'presentation'='Envase de 20 L' and (source_capture->'products'->1->>'quantity')::numeric=1 from public.application_orders),'presentación se archiva y no multiplica la cantidad total');
select pg_temp.assert_true(public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products}',jsonb_build_array(pg_temp.image_source()->'products'->2,pg_temp.image_source()->'products'->1,pg_temp.image_source()->'products'->0))),pg_temp.image_stages(),pg_temp.image_products())='e9000000-0000-4000-8000-000000000001'::uuid,'reintento normaliza orden de productos fuente');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data()||jsonb_build_object('source_capture',jsonb_set(pg_temp.image_source(),'{products,0,presentation}','"Otra presentación"')),pg_temp.image_stages(),pg_temp.image_products())$q$,'UUID','mismo UUID con otros metadatos se rechaza');
select pg_temp.expect_error($q$update public.application_orders set source_capture=null$q$,'permission denied','administración no modifica fuente por DML directo');
reset role;
select pg_temp.expect_error($q$update public.application_orders set source_capture=null$q$,'históricos','guarda protege fuente original incluso con escritura privilegiada');
-- Empate exacto y frontera de áreas enormes: evita un redondeo previo de numeric /.
select pg_temp.assert_true(rcfito_private.normalized_application_image_source(pg_temp.image_source())->>'kind'='image_totals','normalizador privado acepta metadatos completos');
select rcfito_private.validate_application_image_doses(jsonb_build_object('kind','image_totals','area_ha',14,'products',jsonb_build_array((pg_temp.image_source()->'products'->0)||'{"quantity":0.000007,"unit":"g"}')),'[{"product_id":"72000000-0000-4000-8000-000000000001","dose":0.000001}]',14);
select pg_temp.assert_true(true,'empate de media millonésima redondea hacia arriba de forma exacta');
select pg_temp.expect_error($q$select rcfito_private.validate_application_image_doses(jsonb_build_object('kind','image_totals','area_ha',4000000000.0001,'products',jsonb_build_array((pg_temp.image_source()->'products'->0)||'{"quantity":2000,"unit":"g"}')),'[{"product_id":"72000000-0000-4000-8000-000000000001","dose":0.000001}]',4000000000.0001)$q$,'fuera del rango','valor justo por debajo del empate no se vuelve positivo por redondeo intermedio');
select rcfito_private.validate_application_image_doses(jsonb_build_object('kind','image_totals','area_ha',14,'products',jsonb_build_array((pg_temp.image_source()->'products'->0)||'{"quantity":99999999.999999,"unit":"g"}')),'[{"product_id":"72000000-0000-4000-8000-000000000001","dose":7142857.142857}]',14);
select pg_temp.assert_true(true,'cantidad grande válida conserva seis decimales sin float');
set local role authenticated;
select public.save_sowing_group(pg_temp.group_data()||'{"id":"e7000000-0000-4000-8000-000000000001","name":"Grupo imagen ficticio"}',pg_temp.image_stages());
select public.create_application_order(pg_temp.order_data('e9000000-0000-4000-8000-000000000002')||'{"source_group_id":"e7000000-0000-4000-8000-000000000001"}',pg_temp.image_stages(),pg_temp.mixture());
select public.create_application_order(pg_temp.image_data('e9000000-0000-4000-8000-000000000003')||'{"source_group_id":"e7000000-0000-4000-8000-000000000001","recipe_source":{"order_id":"e9000000-0000-4000-8000-000000000002","revision":0}}',pg_temp.image_stages(),pg_temp.image_products());
select pg_temp.assert_true((select selection_origin='group' and source_group_id='e7000000-0000-4000-8000-000000000001' and recipe_source_order_id='e9000000-0000-4000-8000-000000000002' and source_capture=pg_temp.image_source() from public.application_orders where id='e9000000-0000-4000-8000-000000000003'),'imagen convive con grupo y receta base sin perder sus snapshots');
select pg_temp.assert_true((select source_capture is null from public.application_orders where id='e9000000-0000-4000-8000-000000000002'),'captura manual anterior conserva source_capture nulo');
select public.correct_project_lot(jsonb_build_object('id','e8000000-0000-4000-8000-000000000001','lot_id',(select d.lot_id from public.sowing_stages s join public.lot_subdivisions d on d.id=s.subdivision_id where s.id=(pg_temp.image_stages())[1]),'expected_version',0,'name','Malla imagen corregida','area_ha',11,'stage_id','e1000000-0000-4000-8000-000000000001','planned_sowing_date','2026-01-01','actual_sowing_date','2026-01-02','reason','Corrección ficticia de superficie'));
select pg_temp.assert_true((select sum(area_ha)=13 from public.sowing_stages where id=any(pg_temp.image_stages())) and (select source_capture=pg_temp.image_source() from public.application_orders where id='e9000000-0000-4000-8000-000000000001'),'corrección de malla conserva totales y área original de imagen');
select pg_temp.assert_true(public.create_application_order(pg_temp.image_data(),pg_temp.image_stages(),pg_temp.image_products())='e9000000-0000-4000-8000-000000000001'::uuid,'reintento confirmado conserva fuente histórica tras corregir área');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data('e9000000-0000-4000-8000-000000000004'),pg_temp.image_stages(),pg_temp.image_products())$q$,'superficie seleccionada cambió','formulario calculado con área anterior se rechaza sin guardar');
select public.create_application_order(pg_temp.image_data('e9000000-0000-4000-8000-000000000004')||jsonb_build_object('source_capture',pg_temp.image_source(13)),pg_temp.image_stages(),'[{"product_id":"72000000-0000-4000-8000-000000000001","dose":2153.846154},{"product_id":"72000000-0000-4000-8000-000000000002","dose":76.923077},{"product_id":"72000000-0000-4000-8000-000000000003","dose":25.615385}]');
select pg_temp.assert_true((select (source_capture->>'area_ha')::numeric=13 from public.application_orders where id='e9000000-0000-4000-8000-000000000004'),'recalcular con superficie vigente permite guardar');
select public.revise_application_order(jsonb_build_object('id','e6000000-0000-4000-8000-000000000001','order_id','e9000000-0000-4000-8000-000000000001','expected_revision',0,'target_ids',(select array_agg(id) from public.application_targets where order_id='e9000000-0000-4000-8000-000000000001'),'method_id','71000000-0000-4000-8000-000000000001','indicated_date','2026-01-03','scheduled_date','2026-01-06','water_l_ha',120,'observations','Nota revisada','reason','Cambio ficticio de mezcla'),pg_temp.mixture());
select pg_temp.assert_true((select revision=1 and source_capture=pg_temp.image_source() from public.application_orders where id='e9000000-0000-4000-8000-000000000001'),'editar indicación conserva evidencia de los totales originalmente aprobados');
select public.perform_application_targets('e9000000-0000-4000-8000-000000000001',array[(select id from public.application_targets where order_id='e9000000-0000-4000-8000-000000000001' and stage_id='e1000000-0000-4000-8000-000000000001')],'{"actual_date":"2026-01-04","changed":false,"expected_revision":1}');
select public.correct_application_target(jsonb_build_object('id','e6000000-0000-4000-8000-000000000002','target_id',(select id from public.application_targets where order_id='e9000000-0000-4000-8000-000000000001' and stage_id='e1000000-0000-4000-8000-000000000001'),'expected_version',0,'actual_date','2026-01-05','water_l_ha',120,'equipment','Equipo ficticio','applicator','','observations','Corrección real ficticia','reason','Corrección de realización ficticia'),'[{"product_id":"72000000-0000-4000-8000-000000000001","dose":20}]');
select pg_temp.assert_true((select source_capture=pg_temp.image_source() and source_text=E'  OCR ficticio\nMallas y contexto revisados  ' from public.application_orders where id='e9000000-0000-4000-8000-000000000001'),'realización y corrección conservan fuente y OCR originales');
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000002';
select pg_temp.assert_true((select source_capture->>'kind'='image_totals' from public.application_orders where id='e9000000-0000-4000-8000-000000000001'),'lector asignado puede consultar metadatos de imagen');
select pg_temp.expect_error($q$select public.create_application_order(pg_temp.image_data('e9000000-0000-4000-8000-000000000005'),pg_temp.image_stages(),pg_temp.image_products())$q$,'administrador','lector no crea indicaciones desde imagen');
set local request.jwt.claim.sub='10000000-0000-4000-8000-000000000003';
select pg_temp.assert_true((select count(*)=0 from public.application_orders where source_capture is not null),'lector sin asignación no ve metadatos de imagen');
reset role;
set local role anon;
select pg_temp.expect_error('select source_capture from public.application_orders','permission denied','anónimo no consulta fuente de imagen');
select pg_temp.expect_error($q$select public.create_application_order(null,null,null)$q$,'permission denied','anónimo no usa RPC de captura');
reset role;
rollback;
